-- Spec 033 — seed the real exams (17 quizzes / 242 questions total) from the drive-materials
-- extraction. This file is part 1 of 4 (the DC Book-Answers exam, 27 questions); parts 2a/2b/2c
-- carry the remaining 16 exams. Idempotent: each quiz inserts only when its title is absent,
-- so reruns insert 0 rows. Provenance is appended to each question's explanation
-- ("— المصدر: file، صpage"); full provenance lives in
-- sandbox/drive-materials/data/extraction/verification-report.md.
-- Data Communication — Book Answers (Ch 2–3)  (27 questions, from quiz-real-dc-book-answers.json)
WITH q AS (
  INSERT INTO public.quizzes (title, description, subject, department, year, status, source_type, duration_seconds)
  SELECT 'اتصالات البيانات — إجابات الكتاب (ف2–3)', '{"description":"Real questions extracted from downloads/data-communication/Book_Answers.pdf — the official solutions manual. Chapter 2 (OSI edition) review questions and the Chapter 3 exercises not covered by the Chapter 3 deck. Answers verbatim from the printed solutions; wrong options constructed. Chapter 1 items were already fully covered by the Chapter 1 deck.","department":"AI","year":"المستوى الثاني","subject":"اتصالات البيانات","semester":"1"}', 'اتصالات البيانات', 'AI', 'المستوى الثاني', 'approved', 'manual', 1620
  WHERE NOT EXISTS (SELECT 1 FROM public.quizzes WHERE title = 'اتصالات البيانات — إجابات الكتاب (ف2–3)')
  RETURNING id
)
INSERT INTO public.quiz_questions (quiz_id, question, options, correct_answer, explanation, order_index)
SELECT q.id, v.question, v.options, v.correct_answer, v.explanation, v.order_index
FROM q, (VALUES
  ('Which layers of the Internet model are the network support layers?', '["Physical, data link, and network layers","Transport and application layers","Session and presentation layers","All five layers equally"]'::jsonb, 0, 'RQ2 (verbatim): the network support layers are the physical, data link, and network layers. — المصدر: Book_Answers.pdf، صp5', 1),
  ('What is the transport layer responsible for, versus the network layer?', '["Transport: process-to-process delivery of the entire message; network: host-to-host delivery of individual packets","Transport: host-to-host; network: process-to-process","Transport: bit transmission; network: framing","They share exactly the same responsibility"]'::jsonb, 0, 'RQ4 (verbatim). — المصدر: Book_Answers.pdf، صp5', 2),
  ('What are headers and trailers in layered communication?', '["Control data added at the beginning and end of each data unit at each layer of the sender, removed at the corresponding receiver layers — carrying addresses, synchronization, and error-detection info","User data appended for speed","Encryption keys added at the application layer only","Physical-layer wire encoding markers"]'::jsonb, 0, 'RQ7 (verbatim). — المصدر: Book_Answers.pdf، صp5', 3),
  ('Which of the following is a concern of the physical layer?', '["Representation of bits, type of encoding, synchronization of bits, transmission rate and mode","Routing across multiple networks","Dividing the message into segments","Mail services and file transfer"]'::jsonb, 0, 'RQ8 (verbatim): physical characteristics of media, representation of bits, encoding, bit synchronization, rate/mode, device connection. — المصدر: Book_Answers.pdf، صp5', 4),
  ('The data link layer is responsible for:', '["Framing data bits, physical (sender/receiver) addresses, data rate control, detection and correction of damaged/lost frames","Host-to-host addressing and routing","Process-to-process delivery of the whole message","User services such as mail"]'::jsonb, 0, 'RQ9 (verbatim). — المصدر: Book_Answers.pdf، صp5-6', 5),
  ('The network layer is concerned with:', '["Delivery of a packet across multiple networks — host-to-host addressing and routing","Framing within a single LAN","Format and code conversion","Session establishment and termination"]'::jsonb, 0, 'RQ10 (verbatim). — المصدر: Book_Answers.pdf، صp6', 6),
  ('The transport layer is responsible for:', '["Dividing the message into manageable segments, reassembling it at the destination, flow and error control","Route selection only","Mechanical interface to the medium","Log-in and log-out procedures"]'::jsonb, 0, 'RQ11 (verbatim). — المصدر: Book_Answers.pdf، صp6', 7),
  ('What is the difference between the physical address, the logical address, and the port address?', '["Physical: local node address used by the data link layer within one network; logical: sender/receiver at the network layer across networks; port: identifies the application process on the station","All three are the same address in different notations","Physical: network-layer; logical: data-link; port: physical","Port: used for routing; logical: used within a LAN"]'::jsonb, 0, 'RQ12 (verbatim). — المصدر: Book_Answers.pdf، صp6', 8),
  ('The application, presentation, and session layers of the OSI model are represented in the Internet model by:', '["The application layer","The transport layer","The session layer","They are dropped entirely"]'::jsonb, 0, 'RQ14 (verbatim): the lowest four layers of OSI correspond to the Internet model layers. — المصدر: Book_Answers.pdf، صp6', 9),
  ('(Ex 16) Match: route determination / flow control / interface to transmission media / access for the end user.', '["Network layer / data link and transport layers / physical layer / application layer","Transport / network / data link / session","Data link / physical / application / transport","Physical / session / presentation / network"]'::jsonb, 0, 'Ex 16 (verbatim). — المصدر: Book_Answers.pdf، صp6', 10),
  ('(Ex 17) Match: reliable process-to-process delivery / route selection / defining frames / providing user services / transmission of bits.', '["Transport / network / data link / application / physical","Network / transport / physical / application / data link","Transport / network / application / data link / physical","Data link / network / transport / session / physical"]'::jsonb, 0, 'Ex 17 (verbatim). — المصدر: Book_Answers.pdf، صp6', 11),
  ('(Ex 19) In OSI: format and code conversion / establishing-managing-terminating sessions / log-in and log-out procedures are the job of which layers?', '["Presentation / session / session","Application / presentation / session","Session / presentation / application","Transport / session / presentation"]'::jsonb, 0, 'Ex 19 (verbatim): format & code conversion and data-representation independence = presentation; session management and log-in/out = session. — المصدر: Book_Answers.pdf، صp7', 12),
  ('(P3-20) A baseband channel''s lowest frequency is 100 Hz and its bandwidth is 2000 Hz. What is the highest frequency?', '["2100 Hz","2000 Hz","1900 Hz","100 Hz"]'::jsonb, 0, 'Solution 20 (verbatim): highest = 100 + 2000 = 2100 Hz. — المصدر: Book_Answers.pdf، صp10', 13),
  ('(P3-21) Two signals are each simple signals. How do their bandwidths compare?', '["The bandwidth of a simple signal is zero, so both bandwidths are the same (zero)","The higher-amplitude one has larger bandwidth","The higher-frequency one has larger bandwidth","Simple signals have infinite bandwidth"]'::jsonb, 0, 'Solution 21 (verbatim): each is a simple signal; bandwidth of a simple signal is zero; so both are the same. — المصدر: Book_Answers.pdf، صp10', 14),
  ('(P3-25) A signal makes 8 cycles in 4 ms. What is its frequency?', '["2 kHz","8 kHz","0.5 kHz","32 kHz"]'::jsonb, 0, 'Solution 25 (verbatim): f = 8 / (4 ms) = 2 kHz. — المصدر: Book_Answers.pdf، صp11', 15),
  ('(P3-29) A digital signal with a 6-MHz bandwidth: data rate using the first harmonic? three harmonics? five harmonics?', '["12 Mbps / 4 Mbps / 2.4 Mbps","6 / 18 / 30 Mbps","3 / 2 / 1.2 Mbps","24 / 8 / 4.8 Mbps"]'::jsonb, 0, 'Solution 29 (verbatim): first harmonic 2 × 6 MHz = 12 Mbps; three harmonics (2 × 6 MHz)/3 = 4 Mbps; five harmonics (2 × 6 MHz)/5 = 2.4 Mbps. — المصدر: Book_Answers.pdf، صp11', 16),
  ('(P3-32) An amplifier has a gain of 4 dB applied three times. What is the total amplification factor?', '["12 dB total → amplified by 15.85","64 dB total → 1,000,000×","7 dB total → 5×","12× directly"]'::jsonb, 0, 'Solution 32 (verbatim): total gain = 3 × 4 = 12 dB; signal amplified by 10^1.2 = 15.85. — المصدر: Book_Answers.pdf، صp11', 17),
  ('(P3-33) How long does it take to send 100,000 bits over a 5-Kbps link?', '["20 s","2 s","0.2 s","200 s"]'::jsonb, 0, 'Solution 33 (verbatim): 100,000 bits / 5 Kbps = 20 s. — المصدر: Book_Answers.pdf، صp12', 18),
  ('(P3-34) A signal travels 480 s at the speed of light (300,000 km/s). What distance does it cover?', '["144,000,000 km","1,440,000 km","625 km","14,400 km"]'::jsonb, 0, 'Solution 34 (verbatim): 480 s × 300,000 km/s = 144,000,000 km. — المصدر: Book_Answers.pdf، صp12', 19),
  ('(P3-37) Shannon capacity of a channel with bandwidth 4000 Hz and SNR = 10/0.005 (signal 10 W, noise 0.005 W)?', '["43,866 bps","4,386 bps","438,660 bps","40,000 bps"]'::jsonb, 0, 'Solution 37 (verbatim): 4,000 log₂(1 + 10/0.005) = 43,866 bps. — المصدر: Book_Answers.pdf، صp12', 20),
  ('(P3-38) A file of 2,000,000 bytes over a 56-Kbps channel vs a 1-Mbps channel?', '["289 s at 56 Kbps; 16 s at 1 Mbps","28.9 s; 1.6 s","2,890 s; 160 s","289 s; 289 s"]'::jsonb, 0, 'Solution 38 (verbatim): file = 2,000,000 × 8 = 16,000,000 bits; 16,000,000/56,000 = 289 s; 16,000,000/1,000,000 = 16 s. — المصدر: Book_Answers.pdf، صp12', 21),
  ('(P3-39) An image is 1200 × 1000 pixels with 1024 possible colors. How many bits to store it?', '["12,000,000 bits","1,200,000 bits","120,000 bits","10,000,000 bits"]'::jsonb, 0, 'Solution 39 (verbatim): log₂1024 = 10 bits/pixel; 1200 × 1000 × 10 = 12,000,000 bits. — المصدر: Book_Answers.pdf، صp12', 22),
  ('(P3-40) The signal power is 200 mW and the noise power is 20 μW (10 × 2 μW per the manual). What is SNR in dB?', '["40 dB","10 dB","100 dB","4 dB"]'::jsonb, 0, 'Solution 40 (verbatim): SNR = 200 mW / 20 μW = 10,000; SNRdB = 10 log₁₀(10,000) = 40. — المصدر: Book_Answers.pdf، صp12', 23),
  ('(P3-41) The signal voltage is 20 times the noise voltage. What are SNR and SNR in dB?', '["SNR = 400; SNRdB ≈ 26.02","SNR = 20; SNRdB ≈ 13","SNR = 4000; SNRdB ≈ 36","SNR = 200; SNRdB ≈ 23"]'::jsonb, 0, 'Solution 41 (verbatim): power ∝ voltage², so SNR = (20/1)² = 400; SNRdB = 10 log₁₀(400) ≈ 26.02. — المصدر: Book_Answers.pdf، صp12', 24),
  ('(P3-42) Using the approximation C = B × (SNRdB/3): a. B=20 KHz, SNRdB=40; b. B=200 KHz, SNRdB=4; c. B=1 MHz, SNRdB=20?', '["a. 267 Kbps; b. 267 Kbps; c. 6.67 Mbps","a. 26.7 Kbps; b. 2.67 Kbps; c. 667 Kbps","a. 800 Kbps; b. 800 Kbps; c. 20 Mbps","a. 267 Mbps; b. 267 Mbps; c. 6.67 Gbps"]'::jsonb, 0, 'Solution 42 (verbatim): C = B × (SNRdB/3) → 20 KHz × (40/3) = 267 Kbps; 200 KHz × (4/3) = 267 Kbps; 1 MHz × (20/3) = 6.67 Mbps. — المصدر: Book_Answers.pdf، صp12', 25),
  ('(P3-44) We need to send 100 Kbps over a 4-KHz noiseless-type channel — what is the minimum SNR in dB (and as a ratio)?', '["SNRdB = 75; SNR ≈ 31,622,776","SNRdB = 25; SNR ≈ 316","SNRdB = 75; SNR = 75","SNRdB = 40; SNR = 10,000"]'::jsonb, 0, 'Solution 44 (verbatim): C = B × (SNRdB/3) → SNRdB = 3 × 100 Kbps / 4 KHz = 75; SNR = 10^(75/10) ≈ 31,622,776. — المصدر: Book_Answers.pdf، صp12-13', 26),
  ('(P3-45) What is the transmission time of a packet of 8,000,000 bits over a link with bandwidth 200,000 bps?', '["40 s","4 s","400 s","0.4 s"]'::jsonb, 0, 'Solution 45 (verbatim): transmission time = packet length / bandwidth = 8,000,000 / 200,000 = 40 s. — المصدر: Book_Answers.pdf، صp13', 27)
) AS v(question, options, correct_answer, explanation, order_index);
